    export default {
        name: 'NuxtError',
        layout: 'error',

        props: {
            error: {
                type: Object,
                default: () => {},
            },
        },

        head() {
            return {
                title: '404 | Page not found',
                meta: [
                    {
                        name: 'robots',
                        content: 'noindex',
                    },
                ],
            };
        },

        mounted() {
            document.querySelector('html').classList.add('overflow-x-hidden');
        },
    };
